import java.util.*;class Patient{final String name;final int severity;final long arrival;Patient(String n,int s,long a){name=n;severity=s;arrival=a;}public String toString(){return name+"(S"+severity+")";}}public class Triage{private long counter;private final PriorityQueue<Patient>queue=new PriorityQueue<>(Comparator.comparingInt((Patient p)->p.severity).thenComparingLong(p->p.arrival));void admit(String n,int s){if(s<1||s>5)throw new IllegalArgumentException("Severity 1..5");queue.add(new Patient(n,s,counter++));}Patient next(){return queue.poll();}public static void main(String[]x){Triage e=new Triage();e.admit("Ravi",3);e.admit("Meena",1);e.admit("John",3);e.admit("Asha",5);e.admit("Kumar",1);e.admit("Lata",2);StringBuilder b=new StringBuilder();Patient p;while((p=e.next())!=null)b.append(p).append(' ');System.out.println(b.toString().trim());}}